import {FEEDS,watchKey,fetchWatchFeed,makeWatchStore,stageWatchEvent,restoreWatchCaptures} from './watch-core.mjs';
import {NEWS_SCOPES,TOPICS} from './osint-core.mjs';
import {extractSourceText} from './collection-text.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function watchDesk({getWorkspace,applyWorkspace,isActive,canChange,uid,today,feedback}){
  const store=makeWatchStore();let scope='world',topic='security',filter='all',busy=false,monitor=false,timer=null,controller=null,generation=0,message='',storageMessage='',report=false,assessmentId='';
  const cacheKey='ruthless-public-watch-v1';
  try{const raw=localStorage.getItem(cacheKey);if(raw){for(const c of restoreWatchCaptures(raw))store.restore(c);message='Restored public-source captures from this browser. Retained data is unverified; refresh due sources.';}}catch{message='Stored collection cache could not be validated; no stored results were loaded.';}
  function persist(){try{const captures=[...store.states.values()].filter(s=>s.capture).map(s=>s.capture).sort((a,b)=>b.checkedAt.localeCompare(a.checkedAt)).slice(0,24);const raw=JSON.stringify({version:1,captures});if(raw.length>2000000)throw new Error('size');localStorage.setItem(cacheKey,raw);storageMessage='';}catch{storageMessage='Collection works, but browser persistence is unavailable or full. Retain the evidence record before closing.';}}
  const key=id=>watchKey(id,scope,topic),selected=()=>Object.keys(FEEDS).map(id=>({id,state:store.states.get(key(id))}));
  function operations(sources){
    const points=[[64,46],[64,126],[64,206],[496,76],[496,186]],count=sources.reduce((n,s)=>n+(s.state?.capture?.events.length??0),0);
    return '<div class="source-operations"><section class="source-topology"><h3>Collection network</h3><p class="muted">Publisher → retained records. Select a source to filter the review queue.</p><svg viewBox="0 0 560 250" role="img" aria-label="Five configured sources connected to the collection store">'+sources.map(({state},i)=>'<path class="'+(busy?'active-edge':'')+'" d="M280 125 Q'+points[i][0]+' 125 '+points[i][0]+' '+points[i][1]+'"/>').join('')+'<circle cx="280" cy="125" r="44"/><text x="280" y="120" text-anchor="middle">RUTHLESS</text><text x="280" y="140" text-anchor="middle">'+count+' RECORDS</text>'+sources.map(({id,state},i)=>'<circle cx="'+points[i][0]+'" cy="'+points[i][1]+'" r="13"/><text x="'+points[i][0]+'" y="'+(points[i][1]+4)+'" text-anchor="middle">'+(state?.capture?.events.length??'—')+'</text><text x="'+points[i][0]+'" y="'+(points[i][1]+31)+'" text-anchor="middle">'+id.toUpperCase()+'</text>').join('')+'</svg><div class="network-controls"><button data-watch-filter="all" aria-pressed="'+(filter==='all')+'">All sources</button>'+sources.map(({id})=>'<button data-watch-filter="'+id+'" aria-pressed="'+(filter===id)+'">'+id.toUpperCase()+'</button>').join('')+'</div></section><section class="source-activity"><h3>Collection activity</h3><p class="muted">Actual completed requests in this session.</p>'+(store.audit.length?'<ol class="activity-list">'+store.audit.slice(-8).reverse().map(a=>'<li><time>'+esc(a.at.slice(11,19))+' UTC</time><span>'+esc(a.key)+'<br>'+esc(a.status==='received'?a.count+' records received':a.error)+'</span></li>').join('')+'</ol>':'<p class="empty">No collection activity yet.<br>Start a collection pass to populate this log.</p>')+'</section></div>';
  }
  function render(){if(!isActive())return;const w=getWorkspace(),sources=selected(),captures=sources.filter(s=>s.state?.capture),failures=sources.filter(s=>s.state?.error),now=Date.now();if(!w.assessments.some(c=>c.id===assessmentId))assessmentId=w.assessments[0]?.id??'';
    const events=captures.flatMap(({id,state})=>(filter==='all'||filter===id)?state.capture.events.map(e=>({e,state})):[]).sort((a,b)=>b.e.sourceTime.localeCompare(a.e.sourceTime));
    document.getElementById('content').innerHTML=`<section class="panel watch-panel" aria-busy="${busy}"><div class="panel-heading"><div><p class="eyebrow">RUTHLESS / GLOBAL COLLECTION</p><h2>Global intelligence watch</h2><p>Live-source collection, change review and traceable intake.</p></div><span class="chip">${monitor?'PAGE-OPEN MONITORING':'ON DEMAND'} · v0.29</span></div><div class="case-body">
      <div class="watch-metrics"><div><strong>${captures.length} / ${sources.length}</strong><span>Sources with retained results</span></div><div><strong>${captures.reduce((n,s)=>n+s.state.capture.events.length,0)}</strong><span>Retained source records</span></div><div><strong>${failures.length}</strong><span>Failed sources this session</span></div></div>
      <div class="osint-controls"><div><label for="watch-scope">News search scope</label><select id="watch-scope"${busy?' disabled':''}>${Object.entries(NEWS_SCOPES).map(([k,v])=>`<option value="${k}"${scope===k?' selected':''}>${esc(v)}</option>`).join('')}</select></div><div><label for="watch-topic">News topic</label><select id="watch-topic"${busy?' disabled':''}>${Object.entries(TOPICS).map(([k,v])=>`<option value="${k}"${topic===k?' selected':''}>${esc(v.label)}</option>`).join('')}</select></div><button id="watch-refresh" class="primary"${busy?' disabled':''}>${busy?'Collecting…':'Collect / refresh due sources'}</button><button id="watch-monitor">${monitor?'Stop monitoring':'Start page-open monitoring'}</button>${busy?'<button id="watch-cancel">Cancel collection</button>':''}</div>
      <p class="muted">Sources refresh at separate 5–60 minute intervals while monitoring is enabled and this view is visible. Failed requests back off; no continuous server worker runs. Browser sleep and publisher delays can interrupt updates. Scope and topic apply only to the news index; the cards describe each other feed’s coverage.</p>
      <p role="status" class="notice">${esc(message||'No source is fetched until you start collection. Missing or quiet feeds do not establish safety.')}</p>
      ${storageMessage?`<p role="status" class="notice">${esc(storageMessage)}</p>`:''}${operations(sources)}<div class="watch-sources">${sources.map(({id,state})=>`<article><h3>${esc(FEEDS[id].label)}</h3><p class="small-label">${esc(FEEDS[id].publisher)}</p><strong class="${state?.error?'error':''}">${state?.error?'Latest attempt failed':state?.capture?.restored?'Restored capture; refresh due sources':state?.capture?(now-Date.parse(state.capture.checkedAt)>FEEDS[id].minutes*60000?'Refresh due':'Recently retrieved'):'Not collected'}</strong><p>${esc(FEEDS[id].scope)}</p>${state?.capture?`<p>Fetched: ${esc(state.capture.checkedAt)}<br>Publisher updated: ${esc(state.capture.publisherUpdatedAt??'Not supplied by feed')}</p><p>${state.delta.baseline?'Baseline capture':`${state.delta.added.length} newly seen · ${state.delta.changed.length} changed · ${state.delta.absent.length} absent from current window`}</p><p class="muted">${state.capture.events.length} retained / ${state.capture.total} returned; ${state.capture.omitted} invalid, duplicate or over-limit records omitted.</p>`:''}${state?.error?`<p class="error">${esc(state.error)}</p>`:''}${state?.nextAt?`<p class="muted">Next eligible request: ${esc(new Date(state.nextAt).toISOString())}</p>`:''}</article>`).join('')}</div>
      <div class="actions"><button id="watch-report">${report?'Hide':'Show'} collection evidence record</button><button data-open-view="osint">Read full advisory passages</button><button data-open-view="media">Inspect incident media</button><button data-open-view="intake">Open document intake</button></div>
      ${report?`<section><h3>Collection evidence record</h3><p>Source response hashes identify retained bytes or normalized captures. They do not authenticate a publisher or prove a reported claim. This record is editable local data, not a signed audit log. Copy it to retain the session.</p><textarea aria-label="Collection evidence JSON" rows="12" readonly>${esc(JSON.stringify({format:'ruthless-watch-evidence',version:1,generatedAt:new Date().toISOString(),sources:sources.map(({id,state})=>({feed:id,scope:FEEDS[id].scope,...state})),attempts:store.audit},null,2))}</textarea></section>`:''}
      <h3>Source records for review</h3><div class="osint-controls"><div><label for="watch-filter">Show records from</label><select id="watch-filter"${busy?' disabled':''}><option value="all">All sources</option>${Object.entries(FEEDS).map(([id,f])=>`<option value="${id}"${filter===id?' selected':''}>${esc(f.label)}</option>`).join('')}</select></div><div><label for="watch-case">Stage into assessment</label><select id="watch-case"${busy?' disabled':''}>${w.assessments.map(c=>`<option value="${esc(c.id)}"${c.id===assessmentId?' selected':''}>${esc(c.title)}</option>`).join('')}</select></div></div>
      <p class="muted">Ordered by source time; the meaning differs by feed. Headlines, advisories, catalog additions and observed natural events are separate evidence types. USGS and EONET retained text summarizes publisher metadata; it is not a verbatim report. Shared topics are not automatic corroboration. Newly seen is relative to this session, not necessarily a new event.</p>
      ${events.length?`<div class="watch-events">${events.map(({e,state},i)=>`<article><p class="small-label">${esc(e.publisher)} · ${esc(e.category)} ${state.delta.baseline?'· BASELINE':state.delta.added.includes(e.id)?'· NEWLY SEEN':state.delta.changed.includes(e.id)?'· CHANGED':''}</p><h3><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.title)}</a></h3><p>${esc(e.timeMeaning)}: ${esc(e.sourceTime)}</p><details><summary>Inspect retained text and provenance</summary><blockquote class="osint-original">${esc(e.excerpt)}</blockquote><p class="muted">Fetched ${esc(state.capture.checkedAt)} · SHA-256 <code class="watch-hash">${esc(state.capture.digest)}</code></p><label class="checkline"><input type="checkbox" id="watch-ack-${i}"><span>I reviewed the source, time meaning and relevance to this assessment.</span></label><button data-watch-stage="${i}"${busy?' disabled':''}>Stage this record for review</button></details></article>`).join('')}</div>`:'<p class="empty">No collected records for this selection. Start collection to inspect real source responses.</p>'}
      <details><summary>Coverage and verification limits</summary><p>Five bounded feeds. No entire-internet coverage or guaranteed real-time detection. Source records do not establish a planned attack, criminal intent or an individual threat. Natural hazards and cyber catalog entries provide their own context; they are not terrorism predictions.</p><p>Recent captures persist in this browser when storage is available; source authenticity is not established by restoration. Change history remains in this tab. Stage selected records and save your workspace to retain them. Media selections and failed-attempt history are not persisted. An item absent from a rolling feed may have aged out; it is not necessarily retracted or resolved.</p></details>
    </div></section>`;
    document.querySelectorAll('[data-watch-stage]').forEach(button=>button.addEventListener('click',()=>{if(!canChange())return;const i=Number(button.dataset.watchStage),{e,state}=events[i];try{applyWorkspace(stageWatchEvent(getWorkspace(),state.capture,e.id,{assessmentId,id:uid('doc'),at:today(),acknowledged:document.getElementById(`watch-ack-${i}`).checked}));message='Real-source record staged in Document intake. Review it before accepting it as evidence.';feedback(message);}catch(error){message=error.message;}render();}));
  }
  async function collect(){if(busy||!isActive()||document.hidden)return;const due=Object.keys(FEEDS).filter(id=>Date.now()>=store.nextAt(id));if(!due.length){message='All sources are within their refresh interval or failure backoff. Previous captures remain available.';render();return;}
    const current=++generation;controller=new AbortController();const signal=controller.signal;busy=true;message=`Collecting ${due.length} due source(s)…`;render();
    await Promise.allSettled(due.map(async id=>{const k=key(id);try{const result=await fetchWatchFeed(id,{scope,topic,extractText:extractSourceText,signal});if(current!==generation)return;store.success(result);persist();}catch(error){if(current!==generation||signal.aborted)return;store.failure(k,id,error instanceof TypeError?new Error('Network, browser policy or publisher unavailable.'):error);}if(current===generation)render();}));
    if(current!==generation)return;busy=false;controller=null;message='Collection pass finished. Inspect each source’s status and timestamps; failed sources were not replaced with sample data.';render();
  }
  function stop(){monitor=false;if(timer)clearInterval(timer);timer=null;if(busy){generation++;controller?.abort();controller=null;busy=false;}message='Monitoring stopped. Retained results remain available.';}
  document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();if(isActive())render();}});
  document.addEventListener('change',e=>{if(!isActive()||busy)return;if(e.target.id==='watch-scope'){stop();scope=e.target.value;}else if(e.target.id==='watch-topic'){stop();topic=e.target.value;}else if(e.target.id==='watch-filter')filter=e.target.value;else if(e.target.id==='watch-case')assessmentId=e.target.value;else return;render();});
  document.addEventListener('click',e=>{if(!isActive())return;const button=e.target.closest('button'),id=button?.id;if(button?.dataset.watchFilter){filter=button.dataset.watchFilter;render();return;}if(id==='watch-refresh')void collect();else if(id==='watch-cancel'){stop();render();}else if(id==='watch-monitor'){if(monitor){stop();render();}else{monitor=true;timer=setInterval(()=>{void collect();},30000);void collect();render();}}else if(id==='watch-report'){report=!report;render();}});
  return {render,stop};
}
